# Tests for the optional geographic exposure export. They use an in-process duckdb CDM built from
# the small synthetic extract in inst/extdata/geo_sample (generated by ARES sample/geo/generate_geo_sample.py).

createGeoSampleCdm <- function(withExposure = TRUE) {
  skip_if_not_installed("duckdb")
  sampleDir <- system.file("extdata", "geo_sample", package = "Achilles")
  skip_if(sampleDir == "", "geo sample data not installed")

  dbFile <- tempfile(fileext = ".duckdb")
  con <- DBI::dbConnect(duckdb::duckdb(), dbdir = dbFile)
  tables <- c("cdm_source", "concept", "location", "location_history", if (withExposure) "external_exposure")
  for (table in tables) {
    DBI::dbExecute(con, sprintf(
      "CREATE TABLE %s AS SELECT * FROM read_csv_auto('%s')",
      table, file.path(sampleDir, paste0(table, ".csv"))
    ))
  }
  DBI::dbDisconnect(con, shutdown = TRUE)
  DatabaseConnector::createConnectionDetails(dbms = "duckdb", server = dbFile)
}

test_that("exportGeoToAres writes aggregated parquet files and a manifest", {
  connectionDetails <- createGeoSampleCdm()
  outputPath <- withr::local_tempdir()

  geoPath <- exportGeoToAres(
    connectionDetails = connectionDetails,
    cdmDatabaseSchema = "main",
    outputPath = outputPath,
    minCellCount = 8
  )

  expect_true(dir.exists(geoPath))
  expect_equal(basename(geoPath), "geo")
  expect_true(file.exists(file.path(outputPath, "GeoSample", "20241021", "geo", "geo_manifest.json")))

  manifest <- jsonlite::fromJSON(file.path(geoPath, "geo_manifest.json"))
  expect_equal(manifest$schemaVersion, 1)
  expect_setequal(manifest$levels, c("county", "state"))
  expect_equal(manifest$minCellCount, 8)
  expect_equal(manifest$periodMin, 2019)
  expect_equal(manifest$periodMax, 2021)
  expect_equal(manifest$nExposures, 3)

  con <- DBI::dbConnect(duckdb::duckdb())
  withr::defer(DBI::dbDisconnect(con, shutdown = TRUE))
  read <- function(file) {
    DBI::dbGetQuery(con, sprintf("SELECT * FROM read_parquet('%s')", file.path(geoPath, file)))
  }

  summary <- read("geo_exposure_summary.parquet")
  expect_setequal(unique(summary$REGION_LEVEL), c("county", "state"))
  expect_setequal(unique(summary$PERIOD), 2019:2021)

  # suppressed cells carry no statistics, reported cells respect the threshold
  suppressed <- summary[summary$SUPPRESSED, ]
  expect_gt(nrow(suppressed), 0)
  expect_true(all(is.na(suppressed$MEAN_VALUE)))
  expect_true(all(is.na(suppressed$N_PERSONS)))
  reported <- summary[!summary$SUPPRESSED, ]
  expect_true(all(reported$N_PERSONS >= 8))
  expect_true(all(reported$P10_VALUE <= reported$MEDIAN_VALUE & reported$MEDIAN_VALUE <= reported$P90_VALUE))

  concepts <- read("geo_exposure_concept.parquet")
  expect_equal(nrow(concepts), 3)
  expect_true(any(grepl("PM2.5", concepts$EXPOSURE_NAME, fixed = TRUE)))
  expect_setequal(concepts$EXPOSURE_CONCEPT_ID, c(2052499839, 2052499957, 2052497544))

  regions <- read("geo_region.parquet")
  expect_true(all(regions$PARENT_REGION_ID[regions$REGION_LEVEL == "county"] %in% c("MI", "OH")))
  # centroids are rounded and never exported for regions below the threshold
  coords <- regions$CENTROID_LAT[!is.na(regions$CENTROID_LAT)]
  expect_equal(coords, round(coords, 2))

  residency <- read("geo_residency.parquet")
  expect_setequal(unique(residency$PERIOD), 2019:2021)
})

test_that("a state is never smaller than any of its counties", {
  connectionDetails <- createGeoSampleCdm()
  geoPath <- exportGeoToAres(connectionDetails, "main", outputPath = withr::local_tempdir(), minCellCount = 1)

  con <- DBI::dbConnect(duckdb::duckdb())
  withr::defer(DBI::dbDisconnect(con, shutdown = TRUE))
  res <- DBI::dbGetQuery(con, sprintf("
    SELECT s.N_PERSONS AS state_n,
           (SELECT MAX(c.N_PERSONS) FROM read_parquet('%1$s') c
             JOIN read_parquet('%2$s') r ON r.REGION_ID = c.REGION_ID AND r.REGION_LEVEL = 'county'
             WHERE c.REGION_LEVEL = 'county' AND r.PARENT_REGION_ID = s.REGION_ID
               AND c.EXPOSURE_CONCEPT_ID = s.EXPOSURE_CONCEPT_ID AND c.PERIOD = s.PERIOD) AS county_n
    FROM read_parquet('%1$s') s WHERE s.REGION_LEVEL = 'state'",
    file.path(geoPath, "geo_exposure_summary.parquet"), file.path(geoPath, "geo_region.parquet")
  ))
  expect_gt(nrow(res), 0)
  # persons are pooled across counties (movers and locations without a county id included)
  expect_true(all(res$state_n >= res$county_n))
})

test_that("the export is skipped quietly when the CDM has no external_exposure", {
  connectionDetails <- createGeoSampleCdm(withExposure = FALSE)
  outputPath <- withr::local_tempdir()

  result <- exportGeoToAres(connectionDetails, "main", outputPath = outputPath)
  expect_null(result)
  expect_false(dir.exists(file.path(outputPath, "GeoSample", "20241021", "geo")))
})

test_that("without a county column only the state level is produced", {
  connectionDetails <- createGeoSampleCdm()
  geoPath <- exportGeoToAres(
    connectionDetails, "main", outputPath = withr::local_tempdir(),
    regionColumns = c(county = "no_such_column", state = "state"), minCellCount = 1
  )
  manifest <- jsonlite::fromJSON(file.path(geoPath, "geo_manifest.json"))
  expect_equal(manifest$levels, "state")
})
